/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    EXU_DeliveryCategory delCat = "TST_DelCat";
    EXU_DeliveryGroupNum deliveryGroupNum = "TST_DeliveryGroup";
    EXU_ProductNum       productNum = "TST_Product";
    ItemId               itemId = "TST_Item";
    str                  priceManagementCode = "TST_PM";

    EXU_DeliveryGroupTable deliveryGroupTable;
    EXU_ProductTable       productTable;
    InventTable            inventTable;
    EXU_ProductExtendTable productExtendTable;


    select firstonly forupdate productExtendTable
        where productExtendTable.ProductNum          == productNum
           && productExtendTable.PriceManagementCode == priceManagementCode;

    if (productExtendTable.RecId)
    {
        ttsbegin;
        productExtendTable.delete();
        ttscommit;

        info(strFmt("Deleted EXU_ProductExtendTable: %1 | %2",
            productNum, priceManagementCode));
    }


    select firstonly forupdate inventTable
        where inventTable.ItemId == itemId;

    if (inventTable.RecId)
    {
        ttsbegin;
        inventTable.delete();
        ttscommit;

        info(strFmt("Deleted InventTable: %1", itemId));
    }


    select firstonly forupdate productTable
        where productTable.ProductNum == productNum;

    if (productTable.RecId)
    {
        ttsbegin;
        productTable.delete();
        ttscommit;

        info(strFmt("Deleted EXU_ProductTable: %1", productNum));
    }


    select firstonly forupdate deliveryGroupTable
        where deliveryGroupTable.DeliveryGroupNum == deliveryGroupNum;

    if (deliveryGroupTable.RecId)
    {
        ttsbegin;
        deliveryGroupTable.delete();
        ttscommit;

        info(strFmt("Deleted DeliveryGroupTable: %1", deliveryGroupNum));
    }
}
